<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#25272b}h1{color:#f37021;font-size:25px}h2{font-size:15px}table{width:100%;border-collapse:collapse;margin-top:20px}th{background:#25272b;color:white;text-align:left}td,th{padding:8px;border-bottom:1px solid #ddd}.muted{color:#777}.summary{background:#fff0e5;padding:16px}</style></head><body><h1>MentoClock</h1><h2>{{$report['business']}} · Attendance report</h2><p>{{$report['start']}} to {{$report['end']}} · {{ucfirst($report['period'])}} · {{$report['timezone']}}</p><div class="summary"><strong>{{number_format($report['total_hours'],2)}} hours</strong> · {{$report['record_count']}} records · {{$report['active_records']}} active</div><table><thead><tr><th>Employee</th><th>Workplace</th><th>Clock in</th><th>Clock out</th><th>Hours in period</th></tr></thead><tbody>@foreach($report['records'] as $r)<tr><td>{{$r['employee']}}</td><td>{{$r['branch']}}</td><td>{{Carbon\Carbon::parse($r['clock_in'])->format('d M Y H:i')}}</td><td>{{$r['clock_out']?Carbon\Carbon::parse($r['clock_out'])->format('d M Y H:i'):'Active'}}</td><td>{{number_format($r['hours'],2)}}</td></tr>@endforeach</tbody></table><p class="muted">Hours are clipped to the selected period. Active records accrue to generation time. Generated {{now()->tz($report['timezone'])->format('d M Y H:i')}}. This is an attendance report; payroll rules are not applied.</p></body></html>
